from datetime import datetime
from airflow.decorators import dag, task

@dag(
    dag_id="taskflow_etl",
    start_date=datetime(2024, 1, 1),
    schedule="@daily",
    catchup=False,
    tags=["taskflow"],
)
def etl_pipeline():

    @task
    def extract() -> dict:
        return {"rows": 100}

    @task
    def transform(data: dict) -> int:
        return data["rows"]  # cleaned count

    @task
    def load(clean_rows: int) -> None:
        print(f"Loading {clean_rows} rows")

    # passing return values wires dependencies AND XComs automatically
    rows = extract()
    clean = transform(rows)
    load(clean)

etl_pipeline()
